def transform(grid):
    out=[row[:] for row in grid]
    pts={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: pts.setdefault(v,[]).append((r,c))
    dots=[v for v in sorted(pts) if len(pts[v])==1]
    if not dots:return out
    v=dots[0]; r,c=pts[v][0]
    boxes=[]
    for k,p in pts.items():
        if k==v or len(p)<4:continue
        a=min(x for x,y in p); b=max(x for x,y in p)
        l=min(y for x,y in p); h=max(y for x,y in p)
        if a<b and l<h and all(grid[x][y]==k for x in range(a,b+1) for y in range(l,h+1) if x in (a,b) or y in (l,h)):
            boxes.append((a,b,l,h))
    for a,b,l,h in boxes:
        for d,e,f,g in boxes:
            if a<d and e<b and l<f and g<h and a<r<b and l<c<h and not(d<=r<=e and f<=c<=g):
                out[r][c]=0
    return out

